From d820dabda396fdfce5fd530ed22f1d14bf819d4e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:41:23 +0100
Subject: [PATCH] applet: add an option to not warn about missing Internet
 access

On machines whose network is not meant to reach the Internet, the tray
icon always showed the limited connectivity badge and a notification. A
new option in the General configuration section turns both of them off.

BUG: 426643
---
 .../qml/ConfigurationDialog.qml               | 11 +++++++-
 kded/connectivitymonitor.cpp                  |  3 +-
 libs/configurationproxy.cpp                   | 16 +++++++++++
 libs/configurationproxy.h                     |  4 +++
 libs/connectionicon.cpp                       |  9 +++++-
 libs/connectionicon.h                         |  1 +
 libs/editor/configuration.cpp                 | 28 +++++++++++++++++++
 libs/editor/configuration.h                   |  4 +++
 libs/editorqml/qml/ConfigurationDialog.qml    |  9 ++++++
 9 files changed, 82 insertions(+), 3 deletions(-)

diff --git a/kcms/kcm_connections/qml/ConfigurationDialog.qml b/kcms/kcm_connections/qml/ConfigurationDialog.qml
index 8aef6875c..015edecf1 100644
--- a/kcms/kcm_connections/qml/ConfigurationDialog.qml
+++ b/kcms/kcm_connections/qml/ConfigurationDialog.qml
@@ -53,10 +53,17 @@ QQC2.ApplicationWindow {
             QQC2.CheckBox {
                 id: systemConnectionsByDefault
                 Layout.fillWidth: true
-                KeyNavigation.down: hotspotName
+                KeyNavigation.down: limitedConnectivityWarning
                 text: i18n("Create new connections as system connections")
             }

+            QQC2.CheckBox {
+                id: limitedConnectivityWarning
+                Layout.fillWidth: true
+                KeyNavigation.down: hotspotName
+                text: i18n("Warn when the network has no Internet access")
+            }
+
             Kirigami.Separator {
                 id: hotspotLabel
                 Kirigami.FormData.label: i18n("Hotspot")
@@ -161,6 +168,7 @@ QQC2.ApplicationWindow {
         unlockModem.checked = PlasmaNM.Configuration.unlockModemOnDetection;
         manageVirtualConnections.checked = PlasmaNM.Configuration.manageVirtualConnections;
         systemConnectionsByDefault.checked = PlasmaNM.Configuration.systemConnectionsByDefault;
+        limitedConnectivityWarning.checked = PlasmaNM.Configuration.limitedConnectivityWarningEnabled;
         hotspotName.text = PlasmaNM.Configuration.hotspotName;
         hotspotPassword.text = PlasmaNM.Configuration.hotspotPassword;
     }
@@ -169,6 +177,7 @@ QQC2.ApplicationWindow {
         PlasmaNM.Configuration.unlockModemOnDetection = unlockModem.checked;
         PlasmaNM.Configuration.manageVirtualConnections = manageVirtualConnections.checked;
         PlasmaNM.Configuration.systemConnectionsByDefault = systemConnectionsByDefault.checked;
+        PlasmaNM.Configuration.limitedConnectivityWarningEnabled = limitedConnectivityWarning.checked;
         PlasmaNM.Configuration.hotspotName = hotspotName.text;
         PlasmaNM.Configuration.hotspotPassword = hotspotPassword.text;
     }
diff --git a/kded/connectivitymonitor.cpp b/kded/connectivitymonitor.cpp
index 0272deecb..602d0b74b 100644
--- a/kded/connectivitymonitor.cpp
+++ b/kded/connectivitymonitor.cpp
@@ -17,6 +17,7 @@

 #include <QCoroDBus>

+#include "configuration.h"
 #include "plasma_nm_kded.h"
 #include <chrono>

@@ -88,7 +89,7 @@ void ConnectivityMonitor::cancelLimitedConnectivityNotificationTimer()

 void ConnectivityMonitor::showLimitedConnectivityNotification()
 {
-    if (m_notification) {
+    if (m_notification || !Configuration::self().limitedConnectivityWarningEnabled()) {
         return;
     }

diff --git a/libs/configurationproxy.cpp b/libs/configurationproxy.cpp
index c1ca036a0..3094e809a 100644
--- a/libs/configurationproxy.cpp
+++ b/libs/configurationproxy.cpp
@@ -119,4 +119,20 @@ void ConfigurationProxy::setSystemConnectionsByDefault(bool opt)
     }
 }

+bool ConfigurationProxy::limitedConnectivityWarningEnabled() const
+{
+    if (!mConfiguration) {
+        return true;
+    }
+
+    return mConfiguration->limitedConnectivityWarningEnabled();
+}
+
+void ConfigurationProxy::setLimitedConnectivityWarningEnabled(bool enabled)
+{
+    if (mConfiguration) {
+        mConfiguration->setLimitedConnectivityWarningEnabled(enabled);
+    }
+}
+
 #include "moc_configurationproxy.cpp"
diff --git a/libs/configurationproxy.h b/libs/configurationproxy.h
index ff8a795ab..98d15bde9 100644
--- a/libs/configurationproxy.h
+++ b/libs/configurationproxy.h
@@ -25,6 +25,7 @@ class PLASMANM_INTERNAL_EXPORT ConfigurationProxy : public QObject
     Q_PROPERTY(bool manageVirtualConnections READ manageVirtualConnections WRITE setManageVirtualConnections NOTIFY manageVirtualConnectionsChanged)
     Q_PROPERTY(bool airplaneModeEnabled READ airplaneModeEnabled WRITE setAirplaneModeEnabled NOTIFY airplaneModeEnabledChanged)
     Q_PROPERTY(bool systemConnectionsByDefault READ systemConnectionsByDefault WRITE setSystemConnectionsByDefault)
+    Q_PROPERTY(bool limitedConnectivityWarningEnabled READ limitedConnectivityWarningEnabled WRITE setLimitedConnectivityWarningEnabled)
     Q_PROPERTY(QString hotspotName READ hotspotName WRITE setHotspotName)
     Q_PROPERTY(QString hotspotPassword READ hotspotPassword WRITE setHotspotPassword)
     Q_PROPERTY(QString hotspotConnectionPath READ hotspotConnectionPath WRITE setHotspotConnectionPath)
@@ -56,6 +57,9 @@ public:
     bool systemConnectionsByDefault() const;
     void setSystemConnectionsByDefault(bool opt);

+    bool limitedConnectivityWarningEnabled() const;
+    void setLimitedConnectivityWarningEnabled(bool enabled);
+
 Q_SIGNALS:
     void airplaneModeEnabledChanged();
     void manageVirtualConnectionsChanged(bool manage);
diff --git a/libs/connectionicon.cpp b/libs/connectionicon.cpp
index 61318b1ee..b832e3d7b 100644
--- a/libs/connectionicon.cpp
+++ b/libs/connectionicon.cpp
@@ -35,6 +35,7 @@ ConnectionIcon::ConnectionIcon(QObject *parent)
     connect(NetworkManager::notifier(), &NetworkManager::Notifier::wirelessHardwareEnabledChanged, this, &ConnectionIcon::wirelessEnabledChanged);
     connect(NetworkManager::notifier(), &NetworkManager::Notifier::wwanEnabledChanged, this, &ConnectionIcon::wwanEnabledChanged);
     connect(NetworkManager::notifier(), &NetworkManager::Notifier::wwanHardwareEnabledChanged, this, &ConnectionIcon::wwanEnabledChanged);
+    connect(&Configuration::self(), &Configuration::limitedConnectivityWarningEnabledChanged, this, &ConnectionIcon::updateLimited);

     for (const NetworkManager::Device::Ptr &device : NetworkManager::networkInterfaces()) {
         if (device->type() == NetworkManager::Device::Ethernet) {
@@ -98,7 +99,13 @@ void ConnectionIcon::setConnectivity(NetworkManager::Connectivity connectivity)
     m_connectivity = connectivity;
     Q_EMIT connectivityChanged(connectivity);

-    const bool limited = (connectivity == NetworkManager::Portal || connectivity == NetworkManager::Limited);
+    updateLimited();
+}
+
+void ConnectionIcon::updateLimited()
+{
+    const bool limited =
+        m_connectivity == NetworkManager::Portal || (m_connectivity == NetworkManager::Limited && Configuration::self().limitedConnectivityWarningEnabled());
     if (m_limited != limited) {
         m_limited = limited;
         Q_EMIT connectionIconChanged(connectionIcon());
diff --git a/libs/connectionicon.h b/libs/connectionicon.h
index fae228ad9..2c25ca777 100644
--- a/libs/connectionicon.h
+++ b/libs/connectionicon.h
@@ -68,6 +68,7 @@ private:
     void setConnectionIcon(const QString &icon);
     void setConnectionTooltipIcon(const QString &icon);
     void setVpn(bool vpn);
+    void updateLimited();
     uint m_signal = 0;
     NetworkManager::WirelessNetwork::Ptr m_wirelessNetwork;

diff --git a/libs/editor/configuration.cpp b/libs/editor/configuration.cpp
index 79c794d74..6697af281 100644
--- a/libs/editor/configuration.cpp
+++ b/libs/editor/configuration.cpp
@@ -235,6 +235,10 @@ void Configuration::onConfigChanged(const KConfigGroup &group, const QByteArrayL
             propManageVirtualConnectionsInitialized = false;
             Q_EMIT manageVirtualConnectionsChanged(manageVirtualConnections());
         }
+
+        if (name == "LimitedConnectivityWarningEnabled") {
+            Q_EMIT limitedConnectivityWarningEnabledChanged();
+        }
     }
 }

@@ -262,4 +266,28 @@ void Configuration::setConnectionNotificationsEnabled(bool enabled)
     }
 }

+bool Configuration::limitedConnectivityWarningEnabled() const
+{
+    KSharedConfigPtr config = KSharedConfig::openConfig(QStringLiteral("plasma-nm"));
+    KConfigGroup grp(config, QStringLiteral("General"));
+
+    if (grp.isValid()) {
+        return grp.readEntry(QStringLiteral("LimitedConnectivityWarningEnabled"), true);
+    }
+
+    return true;
+}
+
+void Configuration::setLimitedConnectivityWarningEnabled(bool enabled)
+{
+    KSharedConfigPtr config = KSharedConfig::openConfig(QStringLiteral("plasma-nm"));
+    KConfigGroup grp(config, QStringLiteral("General"));
+
+    if (grp.isValid()) {
+        grp.writeEntry(QStringLiteral("LimitedConnectivityWarningEnabled"), enabled, KConfigBase::Notify);
+        grp.sync();
+        Q_EMIT limitedConnectivityWarningEnabledChanged();
+    }
+}
+
 #include "moc_configuration.cpp"
diff --git a/libs/editor/configuration.h b/libs/editor/configuration.h
index f9ea9ce8f..2b3eb0687 100644
--- a/libs/editor/configuration.h
+++ b/libs/editor/configuration.h
@@ -44,12 +44,16 @@ public:
     bool connectionNotificationsEnabled() const;
     void setConnectionNotificationsEnabled(bool enabled);

+    bool limitedConnectivityWarningEnabled() const;
+    void setLimitedConnectivityWarningEnabled(bool enabled);
+
     static Configuration &self();

 Q_SIGNALS:
     void airplaneModeEnabledChanged();
     void manageVirtualConnectionsChanged(bool manage);
     void connectionNotificationsEnabledChanged(bool enabled);
+    void limitedConnectivityWarningEnabledChanged();

 private:
     Configuration();
diff --git a/libs/editorqml/qml/ConfigurationDialog.qml b/libs/editorqml/qml/ConfigurationDialog.qml
index 99e8fe3cc..7a72e12ba 100644
--- a/libs/editorqml/qml/ConfigurationDialog.qml
+++ b/libs/editorqml/qml/ConfigurationDialog.qml
@@ -52,8 +52,15 @@ QQC2.ApplicationWindow {
             QQC2.CheckBox {
                 id: systemConnectionsByDefault
                 Layout.fillWidth: true
+                KeyNavigation.down: limitedConnectivityWarning
                 text: i18n("Create new connections as system connections")
             }
+
+            QQC2.CheckBox {
+                id: limitedConnectivityWarning
+                Layout.fillWidth: true
+                text: i18n("Warn when the network has no Internet access")
+            }
         }
     }

@@ -100,12 +107,14 @@ QQC2.ApplicationWindow {
         unlockModem.checked = PlasmaNM.Configuration.unlockModemOnDetection;
         manageVirtualConnections.checked = PlasmaNM.Configuration.manageVirtualConnections;
         systemConnectionsByDefault.checked = PlasmaNM.Configuration.systemConnectionsByDefault;
+        limitedConnectivityWarning.checked = PlasmaNM.Configuration.limitedConnectivityWarningEnabled;
     }

     function saveConfiguration() {
         PlasmaNM.Configuration.unlockModemOnDetection = unlockModem.checked;
         PlasmaNM.Configuration.manageVirtualConnections = manageVirtualConnections.checked;
         PlasmaNM.Configuration.systemConnectionsByDefault = systemConnectionsByDefault.checked;
+        PlasmaNM.Configuration.limitedConnectivityWarningEnabled = limitedConnectivityWarning.checked;
     }

     onVisibleChanged: {
-- 
